scwin.trigger1_onclick = function() {
    var tabNm = "iframe",
        tabKey = "test_" + scwin.guid++;
    var tabOptions = {
        label: tabNm,
        closable: true,
        openAction: "select"
    };
    var contentsOptions = {
        frameMode: "iframe",
        src: "tabcontrol_spaAuto_WPFF-139_(WSQ-3303)_sub.xml"
    };
    var ret = tabControl1.addTab(tabKey, tabOptions, contentsOptions);
    //선택한 tab 활성화.
    if (ret) {
        tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabKey));
    }
};
scwin.trigger2_onclick = function() {
    scwin.guid++;
    var tabNm = "wframe",
        tabKey = "test_" + scwin.guid;
    var tabOptions = {
        label: tabNm,
        closable: true,
        openAction: "select"
    };
    var contentsOptions = {
        wframe: true,
        frameMode: "wframe",
        src: "tabcontrol_spaAuto_WPFF-139_(WSQ-3303)_sub.xml",
        scope: true
    };
    var ret = tabControl1.addTab(tabKey, tabOptions, contentsOptions);
    //선택한 tab 활성화.
    if (ret) {
        tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabKey));
    }
};
scwin.trigger3_onclick = function() {
    var tabNm = "wframePreload",
        tabKey = "test_" + scwin.guid++;
    var tabOptions = {
        label: tabNm,
        closable: true,
        openAction: "select"
    };
    var contentsOptions = {
        //wframe : true,
        frameMode: "wframePreload",
        src: "tabcontrol_spaAuto_WPFF-139_(WSQ-3303)_sub.xml",
        scope: true
    };
    var ret = tabControl1.addTab(tabKey, tabOptions, contentsOptions);
    //선택한 tab 활성화.
    if (ret) {
        tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabKey));
    }
};
scwin.trigger4_onclick = function(e) {
    windowLength = window.length;
    //alert(window.length);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. main 샘플실행 후 3초대기 후 'window.length'버튼을 클릭한다.
    //1. After executing main sample, click 'window.length' button after 3 invitations.
    WebSquare.wUnit.addCommand("pause", "8000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    //Verify step 1. '1'값이 보여진다.(빈 iframe이 1개성성됨)(이전에는 빈 iframe이 0개 생성됨)
    //1. A value of '1' is shown (one empty iframe is generated) (previously zero empty iframes were created)
    WebSquare.wUnit.addCommand("assert", "windowLength == '1'", "true");
    //Test step 2. 'addTab(iframe)'버튼을 2번 클릭하고 3초대기 후 'window.length'버튼을 클릭한다.
    //2. Click the 'addTab (iframe)' button twice. 3 Click the 'window.length' button after the invitation.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "5000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 2. 상단에 iframe tab이 2개 생성되어지고 '3'값이 보여진다.(이전에는 빈 iframe이 2개 생성됨)
    //2. Two iframe tabs are created at the top and a '3' value is displayed (previously two empty iframes are created).
    WebSquare.wUnit.addCommand("assert", "windowLength == '3'", "true");
    //Test step 3. 'addTab(iframe)'버튼을 2번 더 클릭하고 3초대기 후 'window.length'버튼을 클릭한다.
    //3. Click the 'addTab (iframe)' button twice more. 3 Click the 'window.length' button after the invitation.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "5000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 3. 상단에 iframe tab이 총 4개 생성되어지고 '4'값이 보여진다.
    //3. A total of four iframe tabs are created at the top and a '4' value is displayed.
    WebSquare.wUnit.addCommand("assert", "windowLength == '4'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.guid = 0;
    window.windowLength = undefined;
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 09-Mar-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
